//! Immutable unchanged-Python observations; never generated by the native checker.
#![cfg(feature = "soundd-daemon-native")]
use openpilot_dev_tools::{
    seal::Result,
    soundd_daemon_check::{self as check, Command, Event, Mode, SampleStage},
};
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::{
    collections::BTreeMap,
    ffi::OsString,
    fs,
    os::unix::{ffi::OsStringExt, fs::symlink},
    path::{Path, PathBuf},
};
fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..")
}
fn original(name: &str) -> Value {
    serde_json::from_slice(
        &fs::read(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("tests/fixtures/soundd-daemon")
                .join(name),
        )
        .unwrap(),
    )
    .unwrap()
}
fn copied_source() -> tempfile::TempDir {
    let copy = tempfile::tempdir().unwrap();
    let m = original("manifest.json");
    for name in m["source_sha256"].as_object().unwrap().keys() {
        let source = root().join(name);
        if !source.exists() && name == "rust/tools/check_soundd_daemon.py" {
            continue;
        }
        let dest = copy.path().join(name);
        fs::create_dir_all(dest.parent().unwrap()).unwrap();
        fs::copy(source, dest).unwrap();
    }
    copy
}
#[test]
fn captured_fixture_hashes_and_counts_are_independent_and_fixed() {
    let bytes = include_bytes!("fixtures/soundd-daemon/manifest.json");
    assert_eq!(
        format!("{:x}", Sha256::digest(bytes)),
        "14dcbee0272317c38d8a804ec5dc47abcd353710cab0d1dbda6fc0417ae82d82"
    );
    let m: Value = serde_json::from_slice(bytes).unwrap();
    assert_eq!(m["candidate_executed_for_expectations"], false);
    assert_eq!(m["source_sha256"].as_object().unwrap().len(), 21);
    for (name, expected) in m["fixtures"].as_object().unwrap() {
        let raw = fs::read(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("tests/fixtures/soundd-daemon")
                .join(name),
        )
        .unwrap();
        assert_eq!(
            format!("{:x}", Sha256::digest(raw)),
            expected.as_str().unwrap(),
            "{name}"
        );
    }
    for (name, key, n) in [
        ("event-controls-original.json", "controls", 18),
        ("sample-controls-original.json", "controls", 21),
        ("packets-original.json", "packets", 10),
        ("cli-original.json", "cases", 15),
        ("failure-original.json", "cases", 6),
    ] {
        assert_eq!(original(name)[key].as_array().unwrap().len(), n);
    }
}
#[test]
fn all_eighteen_original_event_and_strict_time_boundaries() {
    for case in original("event-controls-original.json")["controls"]
        .as_array()
        .unwrap()
    {
        let mode = Mode::parse(case["mode"].as_str().unwrap()).unwrap();
        let events: Vec<Event> = serde_json::from_value(case["events"].clone()).unwrap();
        let code = if matches!(mode, Mode::Exhausted | Mode::Inactive | Mode::StartFailed) {
            1
        } else {
            0
        };
        assert_eq!(
            check::validate_events(mode, case["pid"].as_u64().unwrap() as u32, code, &events)
                .is_ok(),
            case["valid"].as_bool().unwrap(),
            "{}",
            case["name"]
        );
    }
}
#[test]
fn all_twenty_one_original_float32_sample_predicates() {
    for case in original("sample-controls-original.json")["controls"]
        .as_array()
        .unwrap()
    {
        let stage = match case["stage"].as_str().unwrap() {
            "engage" => SampleStage::Engage,
            "language" => SampleStage::Language,
            "main-held" => SampleStage::MainHeld,
            "enabled-timeout" => SampleStage::EnabledTimeout,
            s => panic!("unknown stage {s}"),
        };
        let mut raw = (0..case["words"].as_u64().unwrap())
            .flat_map(|_| (case["fill_bits"].as_u64().unwrap() as u32).to_le_bytes())
            .collect::<Vec<_>>();
        for edit in case["edits"].as_array().unwrap() {
            let at = edit[0].as_u64().unwrap() as usize * 4;
            raw[at..at + 4].copy_from_slice(&(edit[1].as_u64().unwrap() as u32).to_le_bytes());
        }
        raw.extend(
            case["trailing_bytes"]
                .as_array()
                .unwrap()
                .iter()
                .map(|b| b.as_u64().unwrap() as u8),
        );
        assert_eq!(
            check::validate_samples(stage, &raw).is_ok(),
            case["valid"].as_bool().unwrap(),
            "{}",
            case["name"]
        );
    }
}
#[test]
fn ten_original_full_schema_packet_bytes_and_service_capacities() {
    for case in original("packets-original.json")["packets"]
        .as_array()
        .unwrap()
    {
        let topic = case["topic"].as_str().unwrap();
        let raw = check::input_packet(
            topic,
            &case["values"],
            case["logMonoTime"].as_u64().unwrap(),
        )
        .unwrap();
        let hex = raw.iter().map(|b| format!("{b:02x}")).collect::<String>();
        assert_eq!(hex, case["wire_hex"].as_str().unwrap(), "{topic}");
        assert_eq!(
            format!("{:x}", Sha256::digest(&raw)),
            case["sha256"].as_str().unwrap()
        );
        assert_eq!(
            check::queue_capacity(topic).unwrap(),
            case["queue_size"].as_u64().unwrap() as usize
        );
    }
    assert!(check::queue_capacity("notASoundTopic").is_err());
    assert!(check::input_packet("notASoundTopic", &Value::Null, 0).is_err());
}
fn args(case: &Value) -> Vec<OsString> {
    case["args_bytes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| {
            OsString::from_vec(
                v.as_array()
                    .unwrap()
                    .iter()
                    .map(|b| b.as_u64().unwrap() as u8)
                    .collect(),
            )
        })
        .collect()
}
#[test]
fn fifteen_original_cli_admission_results_and_error_text() {
    for case in original("cli-original.json")["cases"].as_array().unwrap() {
        let observed = check::parse(&args(case), Path::new("/"), BTreeMap::new());
        if case["code"] == 0 {
            assert!(matches!(observed, Ok(Command::Help)), "{}", case["name"]);
        } else {
            let error = observed.unwrap_err();
            let expected = case["stderr"]
                .as_str()
                .unwrap()
                .replace("check_soundd_daemon.py", "check-soundd-daemon");
            assert_eq!(
                error.to_string(),
                expected.trim_end_matches('\n'),
                "{}",
                case["name"]
            );
        }
    }
}
#[test]
fn raw_paths_default_roster_and_duplicate_options_are_preserved() -> Result<()> {
    let args = vec![
        "--binary".into(),
        "ignored".into(),
        "--binary".into(),
        OsString::from_vec(b"./raw-\xff//daemon".to_vec()),
        "--output".into(),
        "./artifacts//./kept".into(),
        "--fixture-assets-binary".into(),
        "helper".into(),
    ];
    let Command::Run(o) = check::parse(&args, Path::new("/owned"), BTreeMap::new())? else {
        panic!("unexpected help")
    };
    assert_eq!(
        o.binary.as_os_str(),
        OsString::from_vec(b"raw-\xff/daemon".to_vec())
    );
    assert_eq!(o.output.as_os_str(), "artifacts/kept");
    assert_eq!(o.fixture_assets_binary, Path::new("/owned/helper"));
    assert_eq!(o.modes, Mode::ALL);
    Ok(())
}
#[test]
fn only_the_exact_retired_checker_may_be_genuinely_absent() {
    let copy = copied_source();
    let retired = copy.path().join("rust/tools/check_soundd_daemon.py");
    if retired.exists() {
        fs::remove_file(&retired).unwrap();
    }
    let live = check::validate_source(copy.path()).unwrap();
    assert!(live.get("rust/tools/check_soundd_daemon.py").is_none());
    assert_eq!(live.as_object().unwrap().len(), 20);
    fs::remove_file(copy.path().join("openpilot/cereal/services.py")).unwrap();
    assert!(check::validate_source(copy.path()).is_err());
}
#[test]
fn present_drift_reintroduced_and_dangling_helpers_reject() {
    let copy = copied_source();
    let retired = copy.path().join("rust/tools/check_soundd_daemon.py");
    if retired.exists() {
        fs::remove_file(&retired).unwrap();
    }
    fs::write(
        &retired,
        b"reintroduced helper is not the captured original",
    )
    .unwrap();
    assert!(check::validate_source(copy.path()).is_err());
    fs::remove_file(&retired).unwrap();
    symlink("absent-original", &retired).unwrap();
    assert!(check::validate_source(copy.path()).is_err());
    fs::remove_file(&retired).unwrap();
    fs::write(
        copy.path().join("rust/tools/fixtures/soundd/portaudio.c"),
        b"changed owned ABI fixture",
    )
    .unwrap();
    assert!(check::validate_source(copy.path()).is_err());
}
#[test]
fn nonregular_source_is_rejected_without_opening_a_blocking_fifo() {
    let copy = copied_source();
    let retired = copy.path().join("rust/tools/check_soundd_daemon.py");
    if retired.exists() {
        fs::remove_file(&retired).unwrap();
    }
    rustix::fs::mkfifoat(
        rustix::fs::CWD,
        &retired,
        rustix::fs::Mode::RUSR | rustix::fs::Mode::WUSR,
    )
    .unwrap();
    assert!(check::validate_source(copy.path()).is_err());
}
